import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.*;
class Tracked implements AutoCloseable {
    // 읽기와 닫기가 언제 일어나는지 출력하는 관찰용 자원이에요.
    boolean fails;
    Tracked(boolean fails) { this.fails = fails; }
    String readLine() {
        System.out.println("read");
        if (fails) throw new IllegalStateException("broken");
        return "시작";
    }
    public void close() { System.out.println("close"); }
}

public class Main {
    public static void main(String[] args) throws Exception {
        boolean broken = false;
        try {
            // 이 자원이 블록을 벗어날 때 꼭 닫히도록 고치세요.
            Tracked resource = new Tracked(broken);
            System.out.println(resource.readLine());
        } catch (IllegalStateException error) {
            System.out.println("failed");
        }
        System.out.println("after");
    }
}

